-- Instala una opción puntual; no cambia horarios ni movimientos existentes.
begin;
set local lock_timeout='5s';
select pg_advisory_xact_lock(hashtextextended('marathon:master-write:v1',0));
create temporary table _exception_before on commit drop as select jsonb_object_agg(name,jsonb_build_object('count',n,'hash',h))snapshot from(select 'agenda_ajustes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_ajustes" x union all select 'agenda_autorizaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_autorizaciones" x union all select 'agenda_cuotas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_cuotas" x union all select 'agenda_horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_horarios" x union all select 'agenda_pausas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_pausas" x union all select 'agenda_periodos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_periodos" x union all select 'agenda_planes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_planes" x union all select 'agenda_tarifas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_tarifas" x union all select 'anticipo_eventos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."anticipo_eventos" x union all select 'anticipos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."anticipos" x union all select 'app_users'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."app_users" x union all select 'attendance_settings'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."attendance_settings" x union all select 'attendance_system_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."attendance_system_audit" x union all select 'bonos_serie'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."bonos_serie" x union all select 'documentos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."documentos" x union all select 'espera'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."espera" x union all select 'horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."horarios" x union all select 'informacion_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."informacion_terapias" x union all select 'master_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."master_audit" x union all select 'movimientos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."movimientos" x union all select 'obras_sociales'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."obras_sociales" x union all select 'operation_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."operation_audit" x union all select 'ortopedia_operaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."ortopedia_operaciones" x union all select 'pacientes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."pacientes" x union all select 'productos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."productos" x union all select 'profesional_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."profesional_terapias" x union all select 'profesionales'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."profesionales" x union all select 'saldo_ajustes_sesion'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_ajustes_sesion" x union all select 'saldo_aplicaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_aplicaciones" x union all select 'saldo_base_legacy'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_base_legacy" x union all select 'saldo_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_config" x union all select 'saldo_cuentas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_cuentas" x union all select 'saldo_eventos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_eventos" x union all select 'saldo_fuentes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_fuentes" x union all select 'saldo_importacion_map'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."saldo_importacion_map" x union all select 'secretarias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."secretarias" x union all select 'sedes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."sedes" x union all select 'shared_space_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."shared_space_config" x union all select 'shared_space_therapies'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."shared_space_therapies" x union all select 'solicitudes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."solicitudes" x union all select 'stock_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."stock_config" x union all select 'terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."terapias" x union all select 'turn_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."turn_audit" x union all select 'turnos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."turnos" x union all select 'user_provision'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."user_provision" x union all select 'user_sedes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."user_sedes" x union all select 'whatsapp_attempts'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."whatsapp_attempts" x union all select 'whatsapp_config'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."whatsapp_config" x union all select 'whatsapp_events'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."whatsapp_events" x union all select 'whatsapp_message_templates'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."whatsapp_message_templates" x)s;
alter table marathon.turnos add column excepcional boolean;
CREATE OR REPLACE FUNCTION marathon.excepcion_cupo(d date, site text, prof text, therapy text, at_hour time without time zone, requested integer, exclude_turn text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
declare exclude_plan uuid:=null;cap int;shared_cap int;dur int;spec text;left_over int;no boolean;people int;own int;begin
 select t.capacidad,t.duracion_min,marathon.master_norm(t.especialidad) into cap,dur,spec from marathon.terapias t
 join marathon.profesional_terapias pt on pt.terapia_id=t.id and pt.profesional_id=prof
 join marathon.profesionales p on p.id=prof and p.estado='ACTIVO'
 join marathon.sedes s on s.nombre=site and s.estado='ACTIVO' where t.id=therapy and t.estado='ACTIVO';
 if cap is null or requested is null or requested<=0 or extract(epoch from at_hour)/60+requested>1440 then return jsonb_build_object('remaining',0,'capacity',coalesce(cap,0),'blocked',true);end if;
 dur=requested;
 select greatest(cap,coalesce(max(t.capacidad),cap)) into shared_cap from marathon.terapias t join marathon.profesional_terapias pt on pt.terapia_id=t.id and pt.profesional_id=prof where t.estado='ACTIVO' and spec<>'' and marathon.master_norm(t.especialidad)=spec;
 with pool as materialized(select a.*,marathon.master_norm(t.especialidad) spec from marathon.agenda_pool(d)a join marathon.terapias t on t.id=a.terapia_id where a.profesional_id=prof and (exclude_plan is null or a.plan_id is distinct from exclude_plan) and(exclude_turn is null or a.id<>exclude_turn))
 select exists(select 1 from pool a where a.hora<at_hour+make_interval(mins=>dur) and at_hour<a.hora+make_interval(mins=>a.duracion_min) and(a.sede<>site or not(a.terapia_id=therapy or(spec<>'' and a.spec=spec)))),
 coalesce(min(least(cap-(select count(*)::int from pool a where a.terapia_id=therapy and a.hora<=cut.at and cut.at<a.hora+make_interval(mins=>a.duracion_min)),shared_cap-(select count(*)::int from pool a where a.hora<=cut.at and cut.at<a.hora+make_interval(mins=>a.duracion_min)))),cap)
 into no,left_over from (select at_hour at union select a.hora from pool a where a.hora>at_hour and a.hora<at_hour+make_interval(mins=>dur))cut;
 select count(*)::int into own from marathon.agenda_pool(d)a where a.profesional_id=prof and (exclude_plan is null or a.plan_id is distinct from exclude_plan) and(exclude_turn is null or a.id<>exclude_turn) and a.hora<at_hour+make_interval(mins=>dur) and at_hour<a.hora+make_interval(mins=>a.duracion_min);
 with pool as materialized(select a.* from marathon.agenda_pool(d)a join marathon.shared_space_therapies g on g.therapy_id=a.terapia_id where a.sede=site and a.estado in('PENDIENTE','PRESENTE') and not a.pausado and (exclude_plan is null or a.plan_id is distinct from exclude_plan) and(exclude_turn is null or a.id<>exclude_turn))
 select coalesce(max((select count(distinct a.dni)::int from pool a where a.hora<=cut.at and cut.at<a.hora+make_interval(mins=>a.duracion_min))),0) into people from(select at_hour at union select a.hora from pool a where a.hora>at_hour and a.hora<at_hour+make_interval(mins=>dur))cut;
 return jsonb_build_object('hora',to_char(at_hour,'HH24:MI'),'remaining',case when no then 0 else greatest(0,left_over) end,'capacity',cap,'shared_capacity',shared_cap,'blocked',no,'professional_count',own,'shared_space_count',people,'duration_min',dur,'end_hour',to_char(at_hour+make_interval(mins=>dur),'HH24:MI'));
end$function$
;
CREATE OR REPLACE FUNCTION marathon.agenda_turno_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p marathon.agenda_planes%rowtype;q jsonb;a uuid;begin
 perform pg_advisory_xact_lock(hashtextextended('marathon:master-write:v1',0));
 if new.excepcional and(new.plan_id is not null or new.original_id is not null or new.fixed_until is not null or new.series_pattern is not null)then raise exception 'La atención excepcional corresponde a un único turno.'using errcode='22023';end if;
 if tg_op='UPDATE'and new.excepcional is distinct from old.excepcional then raise exception 'No se puede cambiar el tipo de una reserva existente.'using errcode='22023';end if;
 if tg_op='INSERT' and new.recovered_from is not null and new.plan_id is null then
  select t.plan_id,t.terapia_override into new.plan_id,new.terapia_override from marathon.turnos t where t.id=new.recovered_from;
  if new.plan_id is not null then new.fecha_habitual=new.fecha;end if;
 end if;
 if new.plan_id is not null then
  select * into strict p from marathon.agenda_planes where id=new.plan_id for update;
  if new.dni<>p.dni or new.terapia_id<>coalesce(new.terapia_override,(select h.terapia_override from marathon.agenda_horarios h where h.id=new.horario_id and h.plan_id=p.id),p.terapia_id) then raise sqlstate '22023' using message='El turno no corresponde al tratamiento.';end if;
  if new.estado in('PRESENTE','AUSENTE') and marathon.agenda_pausado(p.id,new.fecha) then raise sqlstate '22023' using message='El tratamiento está pausado; conserva su lugar y no registra faltas.';end if;
  if new.estado='PRESENTE' and p.baja is not null and new.fecha>=p.baja then raise sqlstate '22023' using message='El tratamiento está dado de baja.';end if;
  if new.estado='PENDIENTE'and p.modalidad='sessions'and marathon.agenda_presentes(p.id)-(case when tg_op='UPDATE'and old.estado='PRESENTE'then 1 else 0 end)>=marathon.agenda_total(p.id)then raise sqlstate '22023'using message='Las sesiones están completas. Registrá una nueva cantidad.';end if;
  if new.estado='PRESENTE' and p.modalidad='sessions' then
   select x.id into a from marathon.agenda_autorizaciones x where x.plan_id=p.id and (select count(*) from marathon.turnos t where t.autorizacion_id=x.id and t.estado='PRESENTE' and t.id<>new.id)<x.cantidad order by x.fecha,x.created_at,x.id limit 1;
   if a is null then raise sqlstate '22023' using message='Se completaron las sesiones autorizadas. Registrá una nueva cantidad.';end if;new.autorizacion_id=a;
  elsif new.estado<>'PRESENTE' then new.autorizacion_id=null;end if;
 end if;
 if new.estado<>'CANCELADO' and (tg_op='INSERT' or old.estado='CANCELADO' or (old.fecha,old.hora,old.sede,old.profesional_id,old.terapia_id) is distinct from(new.fecha,new.hora,new.sede,new.profesional_id,new.terapia_id)) then
  if exists(select 1 from marathon.agenda_pool(new.fecha)x where x.dni=new.dni and x.id<>new.id and not(x.plan_id is not distinct from new.plan_id and new.horario_id is not null and x.id='H-'||new.horario_id::text||'-'||new.fecha_habitual::text) and x.hora<new.hora+make_interval(mins=>new.duracion_min) and new.hora<x.hora+make_interval(mins=>x.duracion_min)) then raise sqlstate '22023' using message='El paciente ya tiene atención o un lugar reservado en ese horario.';end if;
  if new.excepcional then q=marathon.excepcion_cupo(new.fecha,new.sede,new.profesional_id,new.terapia_id,new.hora,new.duracion_min,new.id);
  else q=marathon.agenda_cupo(new.fecha,new.sede,new.profesional_id,new.terapia_id,new.hora,new.plan_id,new.id);end if;
  if coalesce((q->>'remaining')::int,0)<1 or coalesce((q->>'blocked')::boolean,true) then raise sqlstate '22023' using message='El horario no tiene cupo o dejó de estar habilitado.';end if;
 end if;return new;
end$function$
;
CREATE OR REPLACE FUNCTION public.marathon_agenda_command(p_request_id text, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '3s'
AS $function$
#variable_conflict use_variable
declare uid uuid:=auth.uid();req marathon.solicitudes%rowtype;hashed text;reply jsonb;old marathon.turnos%rowtype;after_row jsonb;
 dates date[];d date;site text;prof text;therapy text;dni text;hour_text text;obs text;cost numeric;duration integer;base_duration integer;
 ids text[]:=array[]::text[];id text;root_id text;state text;slot record;paid numeric;ver bigint;coverage jsonb;reason text;bonus jsonb;fixed_dates date[];fixed_until date;fixed_days integer[];member marathon.turnos%rowtype;series_days integer[];series_pattern jsonb;
begin
 perform 1 from marathon.app_users where user_id=uid and active for share;
 if not found then raise sqlstate '42501' using message='Acceso no autorizado.';end if;
 if p_request_id is null or p_request_id !~ '^[a-zA-Z0-9_-]{12,100}$' or p_action is null or p_action not in ('book','status','coverage','fixed_end','bonus_pay','bonus_refund','bonus_cancel','advance_deposit','advance_apply','advance_refund') or p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>20000 then raise sqlstate '22023' using message='Solicitud inválida.';end if;
 if current_setting('transaction_isolation')<>'read committed' then raise sqlstate '22023' using message='La agenda requiere transacciones READ COMMITTED.';end if;
 hashed=encode(sha256(convert_to(jsonb_build_object('action',p_action,'data',p_data)::text,'UTF8')),'hex');
 insert into marathon.solicitudes(id,usuario_id,tipo,payload_hash) values(p_request_id,uid,'agenda:'||p_action,hashed) on conflict on constraint solicitudes_pkey do nothing;
 select * into req from marathon.solicitudes s where s.id=p_request_id for update;
 if req.id is null or req.usuario_id<>uid or req.tipo<>'agenda:'||p_action or req.payload_hash<>hashed then raise sqlstate '22023' using message='Identificador de solicitud utilizado con otros datos.';end if;
 if req.resultado is not null then return req.resultado;end if;
 -- Mismo orden y mismo candado que el mantenimiento de maestros. Tres usuarios: prima la integridad.
 -- VOLATILE (valor predeterminado) permite leer el estado confirmado después de esperar el candado.
 perform pg_advisory_xact_lock(hashtextextended('marathon:master-write:v1',0));
 if exists(select 1 from jsonb_object_keys(p_data) k where k<>all(case p_action when 'book' then array['dates','sede','prof','therapy','dni','hora','importe','observaciones','coverage','fixed_from','fixed_until','fixed_days','series_days','bonus_amount','bonus_paid','bonus_medium'] when 'coverage' then array['id','version','coverage','motivo'] when 'bonus_pay' then array['id','version','monto','medio','observaciones'] when 'bonus_refund' then array['id','version','monto','medio','observaciones'] when 'bonus_cancel' then array['id','version','motivo'] when 'advance_deposit' then array['dni','sede','therapy','prof','monto','medio','observaciones','apply_existing'] when 'advance_apply' then array['dni'] when 'advance_refund' then array['id','version','monto','medio','observaciones'] when 'fixed_end' then array['id','version'] else array['id','version','estado'] end)) then raise sqlstate '22023' using message='La solicitud contiene campos no admitidos.';end if;
 if p_action='book' then
  site=marathon.master_text(p_data,'sede',40,true);prof=marathon.master_text(p_data,'prof',100,true);therapy=marathon.master_text(p_data,'therapy',100,true);
  dni=marathon.master_text(p_data,'dni',12,true);hour_text=marathon.master_text(p_data,'hora',5,true);obs=marathon.master_text(p_data,'observaciones',1000);
  if dni !~ '^[0-9]{1,12}$' or not exists(select 1 from marathon.pacientes p where p.dni=dni) then raise sqlstate '22023' using message='Buscá y seleccioná un paciente registrado.';end if;
  if hour_text !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or jsonb_typeof(p_data->'importe') is distinct from 'number' or coalesce(p_data->>'importe','') !~ '^[0-9]{1,10}(\.[0-9]{1,2})?$' then raise sqlstate '22023' using message='Hora o importe inválidos (hasta dos decimales).';end if;
  cost=(p_data->>'importe')::numeric;
  if p_data?'coverage' then coverage=marathon.normalize_turn_coverage(dni,p_data->'coverage');end if;
  if jsonb_typeof(p_data->'dates') is distinct from 'array' or jsonb_array_length(p_data->'dates') not between 1 and 60 then raise sqlstate '22023' using message='Seleccioná entre 1 y 60 fechas.';end if;
  if exists(select 1 from jsonb_array_elements(p_data->'dates') x where jsonb_typeof(x)<>'string') then raise sqlstate '22023' using message='Fecha inválida.';end if;
  select array_agg(marathon.agenda_date(value) order by value) into dates from jsonb_array_elements_text(p_data->'dates');
  if cardinality(dates)<>(select count(distinct x) from unnest(dates) x) then raise sqlstate '22023' using message='Hay fechas repetidas en la reserva.';end if;
  if p_data ?| array['fixed_until','fixed_from','fixed_days'] then
   fixed_dates=marathon.fixed_dates(p_data->>'fixed_from',p_data->>'fixed_until',p_data->'fixed_days');
   if dates<>fixed_dates then raise sqlstate '22023' using message='El horario fijo debe incluir todas las fechas hasta la revisión.';end if;
   fixed_until=marathon.agenda_date(p_data->>'fixed_until');
   select array_agg(x::int order by x::int) into fixed_days from jsonb_array_elements_text(p_data->'fixed_days')x;
  end if;
     if p_data?'series_days' then
    if jsonb_typeof(p_data->'series_days') is distinct from 'array' or jsonb_array_length(p_data->'series_days') not between 1 and 7 or exists(select 1 from jsonb_array_elements_text(p_data->'series_days') x where x !~ '^[0-6]$') then raise sqlstate '22023' using message='Días semanales inválidos.';end if;
    select array_agg(distinct x::int order by x::int) into series_days from jsonb_array_elements_text(p_data->'series_days') x;
    if cardinality(series_days)<>jsonb_array_length(p_data->'series_days') or exists(select 1 from unnest(dates) x where extract(dow from x)::int<>all(series_days)) then raise sqlstate '22023' using message='Los días de la serie no coinciden con las fechas elegidas.';end if;
    if fixed_days is not null and fixed_days<>series_days then raise sqlstate '22023' using message='Los días del horario fijo no coinciden con la serie.';end if;
   else
    select array_agg(distinct extract(dow from x)::int order by extract(dow from x)::int) into series_days from unnest(dates) x;
   end if;
   series_pattern=jsonb_build_object('days',series_days,'hora',hour_text,'source',case when p_data?'series_days' then 'selected' else 'inferred' end);
select t.duracion_min into duration from marathon.terapias t where t.id=therapy and t.estado='ACTIVO';
  if duration is null then raise sqlstate '22023' using message='La terapia ya no está activa. Actualizá los datos de agenda.';end if;
  base_duration=duration;
  foreach d in array dates loop
   duration=marathon.session_minutes(d,site,prof,hour_text::time,base_duration);
   select * into slot from marathon.agenda_slots(d,site,prof,therapy) s where s.hora=hour_text;
   if slot.hora is null or slot.remaining<1 or slot.blocked then raise sqlstate 'PT409' using message='Sin cupo el '||d||' a las '||hour_text||'. No se guardó ningún turno de la reserva.';end if;
   if exists(select 1 from marathon.turnos t where t.dni=dni and t.fecha=d and t.estado<>'CANCELADO' and t.hora<(hour_text::time+duration*interval '1 minute') and hour_text::time<(t.hora+marathon.session_minutes(t.fecha,t.sede,t.profesional_id,t.hora,t.duracion_min)*interval '1 minute')) then raise sqlstate 'PT409' using message='El paciente ya tiene un turno que se superpone el '||d||'. No se guardó la reserva.';end if;
   id='TUR-'||gen_random_uuid()::text;if root_id is null then root_id=id;end if;
   insert into marathon.turnos(id,original_id,fecha,sede,hora,duracion_min,terapia_id,profesional_id,dni,importe,estado,observaciones,booking_notes,series_pattern,coverage,fixed_until,fixed_days,created_by,updated_by)
    values(id,case when id=root_id then null else root_id end,d,site,hour_text::time,duration,therapy,prof,dni,cost,'PENDIENTE',obs,obs,series_pattern,coverage,fixed_until,fixed_days,uid,uid);
   select to_jsonb(t) into after_row from marathon.turnos t where t.id=id;
   insert into marathon.turn_audit(request_id,actor,turn_id,action,after_data) values(p_request_id,uid,id,p_action,after_row);ids=array_append(ids,id);
  end loop;
  bonus=marathon.bonus_create(p_request_id,root_id,p_data);
  reply=jsonb_build_object('ids',ids,'coverage',coverage,'bonus',bonus,'sessions',(select jsonb_agg(jsonb_build_object('fecha',t.fecha,'hora',to_char(t.hora,'HH24:MI'),'end_hour',to_char(t.hora+t.duracion_min*interval '1 minute','HH24:MI'),'duration_min',t.duracion_min) order by t.fecha,t.hora,t.id) from marathon.turnos t where t.id=any(ids)),'message',case when cardinality(ids)=1 then 'Turno reservado.' else cardinality(ids)||' turnos reservados.' end);
 elsif p_action='fixed_end' then
  id=marathon.master_text(p_data,'id',100,true);ver=marathon.operation_version(p_data);
  select * into old from marathon.turnos t where t.id=id for update;
  if not found or old.fixed_until is null then raise sqlstate '22023' using message='No se encontró un horario fijo.';end if;
  if old.version<>ver then raise sqlstate 'PT409' using message='El turno cambió. Actualizá la agenda.';end if;
  for member in select t.* from marathon.turnos t where coalesce(t.original_id,t.id)=coalesce(old.original_id,old.id)
   and t.fecha>=old.fecha and t.fecha>=(now() at time zone 'America/Argentina/Buenos_Aires')::date and t.estado='PENDIENTE' order by t.fecha,t.hora,t.id for update loop
   if marathon.turn_paid(member.id)>0 then raise sqlstate 'PT409' using message='Hay un turno con cobros. Reintegrá antes de finalizar el fijo.';end if;
   update marathon.turnos t set estado='CANCELADO' where t.id=member.id;
   select to_jsonb(t) into after_row from marathon.turnos t where t.id=member.id;
   insert into marathon.turn_audit(request_id,actor,turn_id,action,before_data,after_data)values(p_request_id,uid,member.id,'fixed_end',to_jsonb(member),after_row);
   ids=array_append(ids,member.id);
  end loop;
  if cardinality(ids)=0 then raise sqlstate '22023' using message='No quedan turnos futuros pendientes para finalizar.';end if;
  reply=jsonb_build_object('ids',ids,'message',cardinality(ids)||' turnos futuros cancelados. Se conservaron asistencia y cobros anteriores.');
 elsif p_action in('bonus_pay','bonus_refund','bonus_cancel') then
  reply=marathon.bonus_change(p_request_id,p_action,p_data);
 elsif p_action in('advance_deposit','advance_apply','advance_refund')then
 reply=marathon.advance_change(p_request_id,p_action,p_data);
 elsif p_action='coverage' then
  id=marathon.master_text(p_data,'id',100,true);reason=marathon.master_text(p_data,'motivo',500,true);
  if length(btrim(reason))<3 then raise sqlstate '22023' using message='Indicá el motivo de la corrección (mínimo 3 caracteres).';end if;
  ver=marathon.operation_version(p_data);
  select * into old from marathon.turnos t where t.id=id for update;
  if not found then raise sqlstate 'PT404' using message='El turno ya no existe.';end if;
  if old.version<>ver then raise sqlstate 'PT409' using message='El turno cambió. Actualizá la agenda.';end if;
  if coalesce(old.coverage->>'type','')<>'' and old.estado<>'PENDIENTE' and not exists(select 1 from marathon.app_users u where u.user_id=uid and u.active and u.role='ADMIN') then raise sqlstate '42501' using message='Solo administración puede corregir la cobertura de un turno que no está pendiente.';end if;
  coverage=marathon.normalize_turn_coverage(old.dni,p_data->'coverage');
  update marathon.turnos t set coverage=coverage where t.id=id;
  select to_jsonb(t) into after_row from marathon.turnos t where t.id=id;
  insert into marathon.turn_audit(request_id,actor,turn_id,action,before_data,after_data) values(p_request_id,uid,id,'coverage',to_jsonb(old),after_row||jsonb_build_object('motivo_cobertura',reason));
  reply=jsonb_build_object('ids',jsonb_build_array(id),'message','Cobertura del turno actualizada. Se conservaron importe, estado y pagos.');
 else
  id=marathon.master_text(p_data,'id',100,true);state=marathon.master_text(p_data,'estado',10,true);
  if state not in ('PENDIENTE','PRESENTE','AUSENTE','CANCELADO') or jsonb_typeof(p_data->'version') is distinct from 'number' or coalesce(p_data->>'version','') !~ '^[0-9]{1,18}$' then raise sqlstate '22023' using message='Estado o versión inválidos.';end if;
  ver=(p_data->>'version')::bigint;
  select * into old from marathon.turnos t where t.id=id for update;
  if not found then raise sqlstate 'PT404' using message='El turno ya no existe.';end if;
  if old.version<>ver then raise sqlstate 'PT409' using message='El turno cambió. Actualizá la agenda antes de modificarlo.';end if;
  select coalesce(sum(case when m.tipo='REINTEGRO' then -m.monto else m.monto end),0) into paid from marathon.movimientos m where m.turno_id=id;
  if state<>'PRESENTE' and paid>0 and not exists(select 1 from marathon.saldo_config where activo) then raise sqlstate '22023' using message='El turno tiene cobros. Registrá el reintegro antes de cambiar su estado.';end if;
     if old.estado='CANCELADO' and state<>'CANCELADO' and exists(select 1 from marathon.turnos r where r.recovered_from=old.id) then raise sqlstate 'PT409' using message='Esta cancelación ya fue recuperada. Consultá la nueva sesión.';end if;
if old.estado='CANCELADO' and state<>'CANCELADO' then
   if old.excepcional then
    select to_char(old.hora,'HH24:MI')hora,(q->>'remaining')::int remaining,(q->>'blocked')::boolean blocked into slot from(select marathon.excepcion_cupo(old.fecha,old.sede,old.profesional_id,old.terapia_id,old.hora,old.duracion_min,old.id)q)x;
   else
   select * into slot from marathon.agenda_slots(old.fecha,old.sede,old.profesional_id,old.terapia_id) s where s.hora=to_char(old.hora,'HH24:MI');
   -- No restaurar con una duración distinta de la que se comprobó.
   if marathon.session_minutes(old.fecha,old.sede,old.profesional_id,old.hora,old.duracion_min)<>(select marathon.session_minutes(old.fecha,old.sede,old.profesional_id,old.hora,t.duracion_min) from marathon.terapias t where t.id=old.terapia_id) then raise sqlstate 'PT409' using message='Cambió la duración de la terapia. Creá una nueva reserva para este turno cancelado.';end if;
   end if;
   if slot.hora is null or slot.remaining<1 or slot.blocked then raise sqlstate 'PT409' using message='El horario ya no tiene cupo. El turno sigue cancelado.';end if;
   if exists(select 1 from marathon.turnos t where t.dni=old.dni and t.fecha=old.fecha and t.estado<>'CANCELADO' and t.hora<old.hora+marathon.session_minutes(old.fecha,old.sede,old.profesional_id,old.hora,old.duracion_min)*interval '1 minute' and old.hora<t.hora+marathon.session_minutes(t.fecha,t.sede,t.profesional_id,t.hora,t.duracion_min)*interval '1 minute') then raise sqlstate 'PT409' using message='El paciente tiene otro turno que se superpone.';end if;
  end if;
  if state<>'PRESENTE' then perform marathon.advance_apply(p_request_id,id,true);end if;
 update marathon.turnos t set estado=state,attendance_manual_date=t.fecha,attendance_auto=false,attendance_auto_at=null where t.id=id;
 if state='PRESENTE'then perform marathon.advance_apply(p_request_id,id);end if;
  select to_jsonb(t) into after_row from marathon.turnos t where t.id=id;
  insert into marathon.turn_audit(request_id,actor,turn_id,action,before_data,after_data) values(p_request_id,uid,id,p_action,to_jsonb(old),after_row);
  reply=jsonb_build_object('ids',jsonb_build_array(id),'message','Estado del turno actualizado.');
 end if;
 update marathon.solicitudes s set resultado=reply where s.id=p_request_id;return reply;
end $function$
;
create function marathon.excepcion_run(p_request_id text,p_data jsonb)returns jsonb language plpgsql set search_path=''set lock_timeout='5s'as $$
declare reply jsonb;d date;site text;prof text;therapy text;person text;at_hour time;duration integer;cost numeric;cov jsonb;memo text;tid text;old marathon.turnos%rowtype;after_row jsonb;begin
 reply=marathon.operation_begin(p_request_id,'agenda:excepcion',p_data);if reply is not null then return reply;end if;
 if exists(select 1 from jsonb_object_keys(p_data)k where k<>all(array['date','site','prof','therapy','dni','time','amount','coverage','notes','id','version']))then raise exception 'La atención excepcional permite un único turno.'using errcode='22023';end if;
 d=marathon.agenda_date(p_data->>'date');site=marathon.master_text(p_data,'site',40,true);prof=marathon.master_text(p_data,'prof',100,true);therapy=marathon.master_text(p_data,'therapy',100,true);person=marathon.master_text(p_data,'dni',12,true);
 if d>marathon.agenda_hoy()+366 then raise exception 'Elegí una fecha hasta un año en adelante.'using errcode='22023';end if;
 if person!~'^[0-9]{1,12}$'or not exists(select 1 from marathon.pacientes where dni=person)then raise exception 'Seleccioná un paciente registrado.'using errcode='22023';end if;
 if coalesce(p_data->>'time','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$'or jsonb_typeof(p_data->'amount')is distinct from'number'or coalesce(p_data->>'amount','')!~'^[0-9]{1,10}(\.[0-9]{1,2})?$'then raise exception 'Revisá la hora y el importe de la sesión.'using errcode='22023';end if;
 at_hour=(p_data->>'time')::time;cost=(p_data->>'amount')::numeric;
 select duracion_min into duration from marathon.terapias where id=therapy and estado='ACTIVO';
 if duration is null then raise exception 'Seleccioná una terapia activa.'using errcode='22023';end if;
 cov=marathon.normalize_turn_coverage(person,p_data->'coverage');memo=coalesce(marathon.master_text(p_data,'notes',1000),'');
 if nullif(p_data->>'id','')is not null then
  select *into old from marathon.turnos where id=p_data->>'id'for update;
  if old.id is null or not coalesce(old.excepcional,false)or old.estado<>'PENDIENTE'or old.dni<>person or old.version<>marathon.operation_version(p_data)then raise exception 'El turno cambió. Volvé a abrir su edición.'using errcode='PT409';end if;
  if marathon.turn_paid(old.id)>0 then raise exception 'El turno tiene pagos aplicados. Revisalos antes de editar.'using errcode='22023';end if;
  tid=old.id;
 else tid='TUR-'||gen_random_uuid()::text;end if;
 if exists(select 1 from marathon.agenda_pool(d)x where x.dni=person and x.id<>tid and x.hora<at_hour+make_interval(mins=>duration)and at_hour<x.hora+make_interval(mins=>x.duracion_min))then raise exception 'El paciente ya tiene una atención o reserva que se superpone.'using errcode='PT409';end if;
 reply=marathon.excepcion_cupo(d,site,prof,therapy,at_hour,duration,tid);
 if coalesce((reply->>'blocked')::boolean,true)or coalesce((reply->>'remaining')::int,0)<1 then raise exception 'El profesional no está habilitado para esa terapia o tiene una atención incompatible en ese horario.'using errcode='PT409';end if;
 if memo not like 'Atención excepcional%'then memo='Atención excepcional'||case when memo=''then''else E'\n'||memo end;end if;
 if old.id is null then
  insert into marathon.turnos(id,fecha,sede,hora,duracion_min,terapia_id,profesional_id,dni,importe,estado,coverage,observaciones,booking_notes,excepcional,attendance_manual_date,created_by,updated_by)
  values(tid,d,site,at_hour,duration,therapy,prof,person,cost,'PENDIENTE',cov,memo,memo,true,case when d<marathon.agenda_hoy()then d end,auth.uid(),auth.uid());
 else
  update marathon.turnos set fecha=d,sede=site,hora=at_hour,duracion_min=duration,terapia_id=therapy,profesional_id=prof,importe=cost,coverage=cov,booking_notes=memo,attendance_manual_date=case when d<marathon.agenda_hoy()then d end where id=tid;
 end if;
 select to_jsonb(t)into after_row from marathon.turnos t where id=tid;
 insert into marathon.turn_audit(request_id,actor,turn_id,action,before_data,after_data)values(p_request_id,auth.uid(),tid,case when old.id is null then'book_exception'else'edit_exception'end,case when old.id is null then null else to_jsonb(old)end,after_row);
 reply=jsonb_build_object('ids',jsonb_build_array(tid),'exceptional',true,'turn',after_row,'message',case when old.id is null then'Atención excepcional reservada. Se conservó el horario habitual.'else'Atención excepcional actualizada.'end);
 update marathon.solicitudes set resultado=reply where id=p_request_id;return reply;
end$$;
create function public.marathon_excepcion_prever(p_data jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare reply jsonb;begin
 if not marathon.active_user()then raise exception 'Acceso no autorizado.'using errcode='42501';end if;
 begin reply=marathon.excepcion_run('preview-'||gen_random_uuid(),p_data);raise exception using errcode='ZP001',message='Solo vista previa';exception when sqlstate 'ZP001'then null;end;
 return reply||jsonb_build_object('preview',true);
end$$;
create function public.marathon_excepcion_guardar(p_request_id text,p_data jsonb)returns jsonb language plpgsql security definer set search_path=''as $$begin return marathon.excepcion_run(p_request_id,p_data);end$$;

revoke all on function marathon.excepcion_cupo(date,text,text,text,time,integer,text),marathon.excepcion_run(text,jsonb),marathon.agenda_turno_guard()from public,anon,authenticated;
revoke all on function public.marathon_excepcion_prever(jsonb),public.marathon_excepcion_guardar(text,jsonb)from public,anon;
grant execute on function public.marathon_excepcion_prever(jsonb),public.marathon_excepcion_guardar(text,jsonb)to authenticated;
do $guard$declare actual jsonb;begin select snapshot into actual from(select jsonb_object_agg(name,jsonb_build_object('count',n,'hash',h))snapshot from(select 'agenda_ajustes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_ajustes" x union all select 'agenda_autorizaciones'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_autorizaciones" x union all select 'agenda_cuotas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_cuotas" x union all select 'agenda_horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_horarios" x union all select 'agenda_pausas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_pausas" x union all select 'agenda_periodos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_periodos" x union all select 'agenda_planes'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_planes" x union all select 'agenda_tarifas'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."agenda_tarifas" x union all select 'anticipo_eventos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."anticipo_eventos" x union all select 'anticipos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."anticipos" x union all select 'app_users'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."app_users" x union all select 'attendance_settings'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."attendance_settings" x union all select 'attendance_system_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."attendance_system_audit" x union all select 'bonos_serie'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."bonos_serie" x union all select 'documentos'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."documentos" x union all select 'espera'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."espera" x union all select 'horarios'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."horarios" x union all select 'informacion_terapias'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."informacion_terapias" x union all select 'master_audit'name,count(*)n,md5(coalesce(jsonb_agg((to_jsonb(x)-'excepcional')order by (to_jsonb(x)-'excepcional')::text collate "C"),'[]')::text)h from marathon."master_audit" x union all select 'movimientos'name,count(*)n,md5(